(function(){
  const workspaceRoutes=['summary','metrics','schedule','notes','team','files','settings'];
  const routes=['projects',...workspaceRoutes];
  const labels={projects:'Proyectos',summary:'Resumen',metrics:'Métricas',schedule:'Escaleta',notes:'Guion',team:'Equipo',files:'Archivos',settings:'Configuración'};
  const typeLabels={concert:'Concierto',festival:'Festival',corporate:'Evento corporativo',ceremony:'Ceremonia',broadcast:'Televisión / streaming',other:'Otro'};
  const accentHex={blue:'#74a7ff',violet:'#a78bfa',cyan:'#22d3ee',green:'#5ee49a',amber:'#f5b942',rose:'#fb7185'};
  const visualThemes={nocturne:{label:'Nocturne',description:'Negro azulado, sobrio y de alto contraste'},violet:{label:'Violet Studio',description:'Violeta profundo para una identidad escénica'},cobalt:{label:'Cobalt Stage',description:'Azul eléctrico para operación intensa'},ember:{label:'Ember Cue',description:'Ámbar cálido para señales y transiciones'}};
  let currentRoute='projects';
  let currentProject=new URLSearchParams(location.search).get('project')||'';
  let currentProjectName='Elige tu evento';
  let currentProjectData=null;
  let projectsCache=[];
  let projectsMeta={ownedCount:0,limit:1,remaining:1,plan:'free',subscriptionStatus:'free'};
  let views={};
  let wizardMode='create';
  let wizardProject=null;
  let wizardStep=1;
  let previewUrl='';
  let currentAccount=null;
  let tutorialStep=0;

  const navIcons={
    summary:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 13h6V4H4v9Zm0 7h6v-4H4v4Zm10 0h6v-9h-6v9Zm0-16v4h6V4h-6Z"/></svg>',
    schedule:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 5h14M5 12h14M5 19h14M8 3v4M13 10v4M17 17v4"/></svg>',
    notes:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 4h14v16H5zM8 8h8M8 12h8M8 16h5"/></svg>',
    team:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8Zm7-1a3 3 0 1 0 0-6M3 21v-2a6 6 0 0 1 12 0v2m1-7a5 5 0 0 1 5 5v2"/></svg>',
    more:'<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="5" cy="12" r="1.5"/><circle cx="12" cy="12" r="1.5"/><circle cx="19" cy="12" r="1.5"/></svg>',
    help:'<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M9.8 9a2.4 2.4 0 0 1 4.5 1.2c0 1.8-2.3 2.1-2.3 3.8M12 18h.01"/></svg>',
    chevron:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m8 10 4 4 4-4"/></svg>'
  };

  const esc=value=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
  const dateLabel=value=>value?new Date(`${value}T12:00:00`).toLocaleDateString('es-CL',{day:'2-digit',month:'short',year:'numeric'}):'Fecha por definir';
  const roleLabel=role=>role==='owner'?'Propietario':role==='admin'?'Administrador':role==='editor'?'Director':'Observador';
  const canManage=project=>['owner','admin'].includes(project?.permission);
  const initials=value=>String(value||'Usuario').trim().split(/\s+/).slice(0,2).map(part=>part[0]||'').join('').toUpperCase()||'U';
  const emptyState=(title,text,action='')=>`<div class="shell-empty-state"><span class="shell-empty-mark" aria-hidden="true">+</span><div><strong>${esc(title)}</strong><p>${esc(text)}</p></div>${action}</div>`;

  function routeFromLocation(){const clean=location.pathname.split('/').pop().replace('.html','');const queryView=new URLSearchParams(location.search).get('view');if(routes.includes(clean))return clean;if(routes.includes(queryView))return queryView;return currentProject?'summary':'projects';}
  function routeUrl(route){if(route==='projects')return'/projects';return `/${route}${currentProject?`?project=${encodeURIComponent(currentProject)}`:''}`;}
  function makeView(id,html){const section=document.createElement('section');section.id=`view-${id}`;section.className='workspace-view';section.dataset.route=id;section.innerHTML=html;return section;}
  function mountBackground(){window.AmbientBackground?.mount({mode:'workspace'});}

  function mountNav(){
    const nav=document.createElement('nav');nav.className='workspace-nav';nav.setAttribute('aria-label','Navegación principal');
    const primaryRoutes=['summary','schedule','notes','team'];
    const secondaryRoutes=['metrics','files','settings'];
    nav.innerHTML=`<div class="workspace-nav-primary"><a class="workspace-nav-brand" href="/projects" data-route="projects" title="Cambiar de evento">T-SHOW</a><span class="workspace-nav-project" id="navProjectName" aria-live="polite" hidden>${esc(currentProjectName)}</span></div><div class="workspace-nav-tabs" aria-label="Herramientas del evento">${primaryRoutes.map(route=>`<a href="/${route}" data-route="${route}">${navIcons[route]}<span>${labels[route]}</span></a>`).join('')}<div class="workspace-tools-wrap"><button class="workspace-tools-button" type="button" id="workspaceTools" aria-expanded="false" aria-controls="workspaceToolsMenu">${navIcons.more}<span>Más</span></button><div class="workspace-tools-menu" id="workspaceToolsMenu" hidden>${secondaryRoutes.map(route=>`<a href="/${route}" data-route="${route}"><span>${labels[route]}</span><small>${route==='metrics'?'Resultados e integraciones':route==='files'?'Documentos y recursos':'Preferencias del evento'}</small></a>`).join('')}</div></div></div><div class="workspace-nav-utility"><button class="workspace-help-button" type="button" id="workspaceHelp" title="Ayuda y recorrido guiado" aria-label="Abrir ayuda">${navIcons.help}</button><a class="workspace-nav-live" id="shellLiveLink" href="live.html">Modo en vivo</a><div class="workspace-nav-account-wrap"><button class="workspace-nav-account workspace-user-button" type="button" id="workspaceAccount" aria-expanded="false" aria-controls="workspaceAccountMenu"><span class="workspace-user-avatar" id="workspaceUserAvatar">U</span><span class="workspace-user-copy"><strong id="workspaceUserName">Mi cuenta</strong><small id="workspaceUserRole">Sesión activa</small></span>${navIcons.chevron}</button><div class="workspace-nav-account-menu" id="workspaceAccountMenu" hidden><div class="account-menu-profile"><span class="workspace-user-avatar" id="workspaceMenuAvatar">U</span><div><strong id="workspaceMenuName">Mi cuenta</strong><small id="workspaceMenuEmail">Cargando perfil…</small></div></div><button type="button" data-route="projects">Cambiar de evento</button><button type="button" data-open-tutorial>Ver recorrido guiado</button><button type="button" data-account-reset>Restablecer mi contraseña</button><button class="account-menu-danger" type="button" id="workspaceLogout">Cerrar sesión</button></div></div></div>`;
    document.body.prepend(nav);
    nav.addEventListener('click',event=>{const link=event.target.closest('[data-route]');if(!link)return;event.preventDefault();if(link.dataset.route==='projects'&&currentRoute!=='projects'){currentProject='';currentProjectData=null;currentProjectName='Elige tu evento';}navigate(link.dataset.route,true);});
    nav.querySelector('[data-route="schedule"]').addEventListener('pointerenter',()=>views.schedule?.querySelector('.timing-table'));
    const accountButton=nav.querySelector('#workspaceAccount'),accountMenu=nav.querySelector('#workspaceAccountMenu');
    const toolsButton=nav.querySelector('#workspaceTools'),toolsMenu=nav.querySelector('#workspaceToolsMenu');
    const closeMenus=()=>{accountMenu.hidden=true;toolsMenu.hidden=true;accountButton.setAttribute('aria-expanded','false');toolsButton.setAttribute('aria-expanded','false');};
    nav.addEventListener('click',event=>{if(event.target.closest('[data-route]'))closeMenus();});
    accountButton.addEventListener('click',()=>{const opening=accountMenu.hidden;closeMenus();accountMenu.hidden=!opening;accountButton.setAttribute('aria-expanded',String(opening));});
    toolsButton.addEventListener('click',()=>{const opening=toolsMenu.hidden;closeMenus();toolsMenu.hidden=!opening;toolsButton.setAttribute('aria-expanded',String(opening));});
    nav.querySelector('#workspaceLogout').addEventListener('click',()=>Auth.logout());
    nav.querySelector('[data-account-reset]').addEventListener('click',()=>{closeMenus();requestPasswordReset('','');});
    nav.querySelector('[data-open-tutorial]').addEventListener('click',()=>{closeMenus();startTutorial();});
    nav.querySelector('#workspaceHelp').addEventListener('click',startTutorial);
    document.addEventListener('click',event=>{if(!nav.contains(event.target))closeMenus();});
    document.addEventListener('keydown',event=>{if(event.key==='Escape')closeMenus();});
  }

  async function loadAccountSummary(){
    try{
      const [user,profileResult]=await Promise.all([Auth.currentUser(),Auth.getProfile().catch(()=>null)]);
      const profile=profileResult?.data||profileResult?.profile||profileResult||{};
      const metadata=user?.user_metadata||{};
      const fullName=[profile.first_name||metadata.first_name,profile.last_name||metadata.last_name].filter(Boolean).join(' ')||user?.email?.split('@')[0]||'Mi cuenta';
      currentAccount={id:user?.id,email:user?.email||profile.email||'',name:fullName};
      const avatar=initials(fullName);
      ['workspaceUserAvatar','workspaceMenuAvatar'].forEach(id=>{const node=document.getElementById(id);if(node)node.textContent=avatar;});
      const name=document.getElementById('workspaceUserName'),menuName=document.getElementById('workspaceMenuName'),email=document.getElementById('workspaceMenuEmail');
      if(name)name.textContent=fullName;if(menuName)menuName.textContent=fullName;if(email)email.textContent=currentAccount.email;
    }catch(_){/* La navegación sigue siendo utilizable si el perfil tarda o falla. */}
  }

  function enhanceGuidance(){
    const hints={
      wizardName:'Ej. Festival de Invierno 2026',
      wizardLocation:'Ej. Teatro Municipal, Antofagasta',
      inviteEmail:'persona@organizacion.cl',
      shellEventName:'Ej. Ceremonia aniversario municipal'
    };
    Object.entries(hints).forEach(([id,value])=>document.getElementById(id)?.setAttribute('placeholder',value));
    const invite=document.getElementById('inviteEmail');
    if(invite&&!document.getElementById('inviteEmailHelp'))invite.insertAdjacentHTML('afterend','<small class="form-help" id="inviteEmailHelp">La persona recibirá un enlace seguro para unirse al proyecto.</small>');
    const settingsTitle=document.querySelector('#view-settings .shell-page-head h1');
    if(settingsTitle)settingsTitle.innerHTML='El evento empieza.<br>Antes de abrir puertas.';
    document.querySelector('#ticketeraEventSelect option[value=""]')?.replaceChildren('Selecciona el evento equivalente');
  }

  function modalMarkup(){return `<div class="shell-modal" id="projectWizard" hidden><div class="shell-modal-backdrop" data-close-modal></div><section class="shell-modal-card" role="dialog" aria-modal="true" aria-labelledby="wizardTitle"><button class="shell-modal-close" type="button" data-close-modal aria-label="Cerrar">×</button><span class="shell-eyebrow" id="wizardKicker">Nuevo proyecto · Paso 1 de 2</span><h2 id="wizardTitle">Dale nombre al evento.</h2><form id="projectWizardForm"><div class="wizard-step" data-step="1"><div class="form-group"><label class="form-label" for="wizardName">Nombre</label><input class="form-control" id="wizardName" maxlength="180" required placeholder="Nombre de la producción"></div><div class="grid-2"><div class="form-group"><label class="form-label" for="wizardType">Tipo</label><select class="form-control" id="wizardType"><option value="concert">Concierto</option><option value="festival">Festival</option><option value="corporate">Evento corporativo</option><option value="ceremony">Ceremonia</option><option value="broadcast">Televisión / streaming</option><option value="other">Otro</option></select></div><div class="form-group"><label class="form-label" for="wizardDate">Fecha</label><input class="form-control" id="wizardDate" type="date"></div></div><div class="form-group"><label class="form-label" for="wizardLocation">Ubicación</label><input class="form-control" id="wizardLocation" maxlength="160" placeholder="Ciudad, recinto o estudio"></div></div><div class="wizard-step" data-step="2" hidden><div class="project-preview accent-blue" id="wizardPreview"><span id="wizardPreviewType">CONCIERTO</span><strong id="wizardPreviewName">Tu próximo evento</strong></div><fieldset class="accent-picker"><legend>Color de acento</legend>${Object.keys(accentHex).map((color,index)=>`<label><input type="radio" name="accent" value="${color}" ${index===0?'checked':''}><span class="accent-swatch accent-${color}" title="${color}"></span></label>`).join('')}</fieldset><div class="form-group"><label class="form-label" for="wizardCover">Portada opcional</label><input class="form-control" id="wizardCover" type="file" accept="image/jpeg,image/png,image/webp"><small class="shell-muted">JPEG, PNG o WebP de hasta 10 MB.</small></div></div><p class="shell-message" id="wizardStatus" hidden></p><div class="shell-actions wizard-actions"><button class="btn btn-secondary" id="wizardBack" type="button" hidden>Anterior</button><button class="btn btn-primary" id="wizardNext" type="button">Continuar</button><button class="btn btn-primary" id="wizardSave" type="submit" hidden>Crear proyecto</button></div></form></section></div><div class="shell-modal" id="inviteModal" hidden><div class="shell-modal-backdrop" data-close-invite></div><section class="shell-modal-card shell-modal-small" role="dialog" aria-modal="true" aria-labelledby="inviteTitle"><button class="shell-modal-close" type="button" data-close-invite aria-label="Cerrar">×</button><span class="shell-eyebrow">Nuevo acceso</span><h2 id="inviteTitle">Invitar al equipo.</h2><form id="inviteForm"><div class="form-group"><label class="form-label" for="inviteEmail">Correo</label><input class="form-control" id="inviteEmail" type="email" required autocomplete="email"></div><div class="role-choice"><label><input type="radio" name="inviteRole" value="editor" checked><span><strong>Director</strong><small>Puede editar la escaleta y operar el evento.</small></span></label><label><input type="radio" name="inviteRole" value="viewer"><span><strong>Observador</strong><small>Puede seguir el proyecto en modo lectura.</small></span></label></div><p class="shell-message" id="inviteStatus" hidden></p><button class="btn btn-primary" type="submit">Enviar invitación</button></form></section></div><div class="shell-modal" id="confirmModal" hidden><div class="shell-modal-backdrop" data-cancel-confirm></div><section class="shell-modal-card shell-modal-small" role="alertdialog" aria-modal="true"><span class="shell-eyebrow">Confirmación</span><h2 id="confirmTitle">¿Continuar?</h2><p class="shell-muted" id="confirmText"></p><div class="shell-actions"><button class="btn btn-secondary" type="button" data-cancel-confirm>Cancelar</button><button class="btn btn-danger" id="confirmAccept" type="button">Confirmar</button></div></section></div>`;}

  function tutorialMarkup(){return `<div class="shell-modal onboarding-modal" id="workspaceTutorial" hidden><div class="shell-modal-backdrop" data-close-tutorial></div><section class="shell-modal-card shell-modal-small onboarding-card" role="dialog" aria-modal="true" aria-labelledby="tutorialTitle"><button class="shell-modal-close" type="button" data-close-tutorial aria-label="Cerrar recorrido">×</button><span class="shell-eyebrow" id="tutorialProgress">Primeros pasos · 1 de 4</span><h2 id="tutorialTitle">Tu espacio de trabajo.</h2><p class="shell-muted" id="tutorialText">Aquí encontrarás lo necesario para preparar y operar cada evento.</p><div class="tutorial-dots" id="tutorialDots" aria-hidden="true"></div><div class="shell-actions tutorial-actions"><button class="btn btn-secondary" id="tutorialPrevious" type="button">Anterior</button><button class="btn btn-primary" id="tutorialNext" type="button">Siguiente</button></div><button class="tutorial-skip" id="tutorialSkip" type="button">Omitir recorrido</button></section></div>`;}

  const tutorialSteps=[
    {target:'#navProjectName',title:'Un proyecto a la vez.',text:'El nombre del evento siempre está visible. Presiónalo para cambiar de proyecto sin perder el contexto.'},
    {target:'.workspace-nav-tabs',title:'Tus herramientas principales.',text:'Resumen, Escaleta, Guion y Equipo están siempre a mano. Las opciones menos frecuentes viven en Más.'},
    {target:'#shellLiveLink',title:'Operación en vivo.',text:'Cuando todo esté preparado, entra aquí para seguir tiempos, bloques y estados durante el evento.'},
    {target:'#workspaceAccount',title:'Tu cuenta y la ayuda.',text:'Desde este menú puedes cambiar de proyecto, repetir este recorrido, restablecer tu contraseña o cerrar sesión.'}
  ];
  function showTutorialStep(index){
    tutorialStep=Math.max(0,Math.min(index,tutorialSteps.length-1));
    document.querySelectorAll('.is-tutorial-target').forEach(node=>node.classList.remove('is-tutorial-target'));
    const step=tutorialSteps[tutorialStep],target=document.querySelector(step.target);
    target?.classList.add('is-tutorial-target');
    document.getElementById('tutorialProgress').textContent=`Primeros pasos · ${tutorialStep+1} de ${tutorialSteps.length}`;
    document.getElementById('tutorialTitle').textContent=step.title;
    document.getElementById('tutorialText').textContent=step.text;
    document.getElementById('tutorialPrevious').disabled=tutorialStep===0;
    document.getElementById('tutorialNext').textContent=tutorialStep===tutorialSteps.length-1?'Terminar':'Siguiente';
    document.getElementById('tutorialDots').innerHTML=tutorialSteps.map((_,i)=>`<i class="${i===tutorialStep?'is-active':''}"></i>`).join('');
  }
  function startTutorial(){const modal=document.getElementById('workspaceTutorial');if(!modal)return;modal.hidden=false;showTutorialStep(0);setTimeout(()=>document.getElementById('tutorialNext')?.focus(),30);}
  function closeTutorial(completed=true){
    const modal=document.getElementById('workspaceTutorial');if(modal)modal.hidden=true;
    document.querySelectorAll('.is-tutorial-target').forEach(node=>node.classList.remove('is-tutorial-target'));
    if(completed)try{localStorage.setItem(`tshow_onboarding_v1:${currentAccount?.id||'user'}`,'done');}catch(_){}
    document.getElementById('workspaceHelp')?.focus();
  }

  function mountViews(){
    const shell=document.createElement('main');shell.className='workspace-shell';
    const schedule=makeView('schedule','');['.header-bar','.main-grid','body > footer'].forEach(selector=>{const node=document.querySelector(selector);if(node)schedule.appendChild(node);});schedule.insertAdjacentHTML('afterbegin',`<header class="shell-page-head"><span class="shell-eyebrow">Escaleta operativa</span><h1>El minuto exacto.<br>Antes de que ocurra.</h1><p>Construye la pauta, ajusta cada transición y mantén a todo el equipo leyendo el mismo evento.</p></header>`);views.schedule=schedule;
    views.projects=makeView('projects',`<header class="project-selector-head"><span class="shell-eyebrow">Tus producciones</span><h1>Elige tu<br>evento.</h1><p>Cada evento conserva su propia pauta, equipo e identidad.</p><span id="projectQuota" class="selector-quota">Cargando eventos…</span></header><section class="project-selector-stage" aria-label="Selector de eventos"><button class="carousel-arrow carousel-prev" type="button" aria-label="Evento anterior">←</button><div class="project-carousel" id="projectCarousel" tabindex="0"><div class="project-card project-card-skeleton"></div></div><button class="carousel-arrow carousel-next" type="button" aria-label="Evento siguiente">→</button></section>`);
    views.summary=makeView('summary',`<div class="shell-hero"><article class="glass-panel shell-editorial"><span class="shell-eyebrow">Centro de operación</span><h1>Todo el evento.<br>En su momento.</h1><p class="shell-lead">Consulta el estado del evento y entra a la escaleta sin interrumpir tu flujo.</p><div class="shell-actions"><button class="btn btn-primary" data-go="schedule">Abrir escaleta</button><a class="btn btn-secondary" id="summaryLiveLink" href="live.html">Modo en vivo</a></div></article><article class="glass-panel shell-status-panel"><span class="shell-eyebrow">Estado actual</span><h2 id="summaryProjectTitle">Proyecto activo</h2><p id="summaryStatus" class="shell-muted">Preparando el proyecto…</p><div class="now-next-card"><span class="shell-eyebrow">Próximo bloque</span><strong id="summaryNext">Sin bloques configurados</strong></div></article></div><article class="glass-panel shell-projects"><div class="panel-title"><div><span class="shell-eyebrow">Identidad</span><h2 id="summaryIdentityName">Proyecto seleccionado</h2></div><button class="btn btn-secondary" data-route-jump="projects">Cambiar proyecto</button></div><div class="summary-identity" id="summaryIdentity"></div><div class="summary-team-meta" id="summaryTeamMeta" aria-live="polite"></div></article>`);
    views.metrics=makeView('metrics',`<header class="shell-page-head"><span class="shell-eyebrow">Resultados del evento</span><h1>Decisiones con datos reales.</h1><p>Conecta la venta de entradas de Ticketera con la operación de T-Show, sin exponer información personal de compradores.</p></header><article class="glass-panel shell-projects metrics-connect"><div class="panel-title"><div><span class="shell-eyebrow">Integración</span><h2>Ticketera</h2></div><button class="btn btn-secondary" id="metricsRefresh" type="button">Actualizar</button></div><p id="metricsStatus" class="shell-muted" role="status">Consultando conexión…</p><div id="ticketeraConnector" class="ticketera-connector"></div></article><section id="metricsDashboard" class="metrics-dashboard" hidden aria-live="polite"><div class="metric-card"><span>Entradas emitidas</span><strong id="metricIssued">0</strong><small id="metricChecked">0 acreditadas</small></div><div class="metric-card"><span>Ingresos aprobados</span><strong id="metricRevenue">$0</strong><small id="metricPayments">0 ventas</small></div><div class="metric-card"><span>Ocupación</span><strong id="metricOccupancy">0%</strong><small id="metricCapacity">Sin aforo definido</small></div><div class="metric-card"><span>Por acreditar</span><strong id="metricPending">0</strong><small>Entradas aún no utilizadas</small></div><article class="glass-panel metric-breakdown"><div class="panel-title"><div><span class="shell-eyebrow">Distribución</span><h2>Entradas por tipo</h2></div></div><div id="metricTicketTypes" class="metric-bars"></div></article><article class="glass-panel metric-breakdown"><div class="panel-title"><div><span class="shell-eyebrow">Accesos</span><h2>Entradas por zona</h2></div></div><div id="metricZones" class="metric-bars"></div></article></section>`);
    views.team=makeView('team',`<header class="shell-page-head"><span class="shell-eyebrow">Equipo</span><h1>Cada persona.<br>Solo lo necesario.</h1><p>Invita, asigna responsabilidades y protege la operación con permisos claros por proyecto.</p></header><article class="glass-panel shell-projects"><div class="panel-title"><div><span class="shell-eyebrow">Accesos</span><h2>Miembros actuales</h2></div><button class="btn btn-primary" id="shellInvite">Invitar persona</button></div><p id="shellTeamStatus" class="shell-muted">Cargando equipo…</p><div id="shellMembers" class="team-list"></div></article><article class="glass-panel shell-projects team-invitations"><div class="panel-title"><div><span class="shell-eyebrow">Pendientes</span><h2>Invitaciones</h2></div></div><div id="shellInvitations" class="team-list"></div></article>`);
    views.files=makeView('files',`<header class="shell-page-head"><span class="shell-eyebrow">Archivos</span><h1>Todo el contexto.<br>En un solo lugar.</h1><p>Centraliza fotografías y material operativo sin exponer credenciales ni enlaces permanentes.</p></header><article class="glass-panel shell-projects shell-form-panel"><div class="panel-title"><div><span class="shell-eyebrow">Cloudflare R2</span><h2>Archivos del proyecto</h2></div></div><p class="shell-muted">Carga segura. Imágenes de hasta 10 MB.</p><div class="form-group"><label class="form-label" for="shellFile">Seleccionar imagen</label><input id="shellFile" class="form-control" type="file" accept="image/jpeg,image/png,image/webp"></div><p id="shellFileStatus" class="shell-message">Esperando un archivo.</p></article>`);
    views.settings=makeView('settings',`<header class="shell-page-head"><span class="shell-eyebrow">Configuración</span><h1>El show empieza.<br>Antes de abrir puertas.</h1><p>Define la identidad del evento y administra sus salidas sin perder el contexto de la pauta.</p></header><article class="glass-panel shell-projects shell-form-panel"><div class="panel-title"><div><span class="shell-eyebrow">Parámetros</span><h2>Configuración del evento</h2></div></div><div class="grid-2"><div class="form-group"><label class="form-label" for="shellEventName">Nombre del evento</label><input id="shellEventName" class="form-control" type="text"></div><div class="form-group"><label class="form-label">Proyecto</label><div id="shellProjectId" class="shell-message"></div></div></div><div class="shell-actions"><button class="btn btn-primary" id="shellApplySettings">Guardar nombre</button><button class="btn btn-secondary" data-go="schedule">Editar horarios</button><button class="btn btn-secondary" id="shellExport">Exportar JSON</button><button class="btn btn-secondary" id="shellPrint">Imprimir / PDF</button></div></article>`);
    views.notes=makeView('notes',`<header class="shell-page-head"><span class="shell-eyebrow">Guion del animador</span><h1>La palabra justa.<br>En el momento exacto.</h1><p>Consulta las indicaciones de cada bloque y mantén a todo el equipo en la misma referencia.</p></header><article class="glass-panel shell-projects shell-form-panel"><div class="panel-title"><div><span class="shell-eyebrow">Vista de lectura</span><h2>Guion y notas</h2></div><select id="notesFilter" class="form-control notes-filter" aria-label="Filtrar guion"><option value="all">Todos los bloques</option><option value="script">Solo con guion</option><option value="upcoming">Solo próximos</option></select></div><p id="notesStatus" class="shell-muted">Cargando guion…</p><div id="notesList" class="notes-list"></div></article>`);
    routes.forEach(route=>shell.appendChild(views[route]));document.body.appendChild(shell);document.body.insertAdjacentHTML('beforeend',modalMarkup()+tutorialMarkup());
    shell.addEventListener('click',event=>{const go=event.target.closest('[data-go]');if(go){event.preventDefault();navigate(go.dataset.go,true);}const jump=event.target.closest('[data-route-jump]');if(jump)navigate(jump.dataset.routeJump,true);});
  }

  async function loadProjects(){const result=await ApiClient.getAllProjects();projectsCache=Object.values(result.data||{});projectsMeta=result.meta||projectsMeta;return result;}
  async function attachCover(card,project){if(!project.coverKey)return;try{const signed=await ApiClient.signedFileUrl(project.coverKey);card.style.setProperty('--cover-image',`url("${String(signed.url).replace(/"/g,'%22')}")`);card.classList.add('has-cover');}catch(_){} }
  function projectCard(project,index){const article=document.createElement('article');article.className=`project-card accent-${project.accentColor||'blue'}`;article.tabIndex=0;article.dataset.projectId=project.id;article.setAttribute('role','button');article.setAttribute('aria-label',`Abrir ${project.eventName}`);article.innerHTML=`<div class="project-card-art"><span class="project-card-index">${String(index+1).padStart(2,'0')}</span>${canManage(project)?`<button class="project-menu-button" type="button" aria-label="Opciones de ${esc(project.eventName)}" aria-expanded="false">•••</button><div class="project-menu" hidden><button type="button" data-project-action="edit">Editar identidad</button><button type="button" data-project-action="duplicate">Duplicar proyecto</button><button type="button" data-project-action="delete">Eliminar proyecto</button></div>`:''}<div class="project-card-copy"><span>${esc(typeLabels[project.projectType]||'Proyecto')}</span><h2>${esc(project.eventName||'Proyecto sin nombre')}</h2><p>${esc(project.location||'Ubicación por definir')}</p></div></div><footer><span>${dateLabel(project.eventDate)}</span><strong>${roleLabel(project.permission)}</strong></footer>`;attachCover(article,project);return article;}
  function createCard(){const article=document.createElement('article');const available=projectsMeta.remaining===null||projectsMeta.remaining>0;article.className=`project-card create-project-card${available?'':' is-disabled'}`;article.tabIndex=available?0:-1;article.dataset.createProject='true';article.setAttribute('role','button');if(!available)article.setAttribute('aria-disabled','true');article.setAttribute('aria-label',available?'Crear evento':'Cupo de eventos alcanzado');article.innerHTML=`<div class="create-symbol">${available?'+':'—'}</div><h2>${available?'Crear evento':'Cupo alcanzado'}</h2><p>${available?'Abre un nuevo espacio para tu próxima producción.':'Activa un plan para crear más eventos.'}</p>`;return article;}

  async function loadProjectSelector(){
    const carousel=document.getElementById('projectCarousel'),quota=document.getElementById('projectQuota');if(!carousel)return;
    document.querySelector('.project-selector-stage')?.classList.remove('is-exiting');
    try{await loadProjects();const limitLabel=projectsMeta.limit===null?'ilimitados':projectsMeta.limit;quota.textContent=`${projectsMeta.ownedCount} de ${limitLabel} eventos propios · Plan ${projectsMeta.plan||'free'}`;carousel.innerHTML='';projectsCache.forEach((project,index)=>carousel.appendChild(projectCard(project,index)));carousel.appendChild(createCard());requestAnimationFrame(()=>updateCarouselFocus());}
    catch(error){quota.textContent='No pudimos sincronizar';carousel.innerHTML=`<div class="shell-message" data-status="error">${esc(error.message)}</div>`;}
  }
  function updateCarouselFocus(){const carousel=document.getElementById('projectCarousel');if(!carousel)return;const center=carousel.scrollLeft+carousel.clientWidth/2;[...carousel.querySelectorAll('.project-card')].forEach(card=>{const cardCenter=card.offsetLeft+card.offsetWidth/2;card.classList.toggle('is-focused',Math.abs(center-cardCenter)<card.offsetWidth*.62);});}
  function moveCarousel(direction){const carousel=document.getElementById('projectCarousel');const cards=[...carousel.querySelectorAll('.project-card')];if(!cards.length)return;let index=Math.max(0,cards.findIndex(card=>card.classList.contains('is-focused')));index=Math.min(cards.length-1,Math.max(0,index+direction));cards[index].scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'nearest',inline:'center'});cards[index].focus({preventScroll:true});}
  async function openProject(project){
    const stage=document.querySelector('.project-selector-stage');
    const card=[...document.querySelectorAll('.project-card')].find(node=>node.dataset.projectId===project.id);
    card?.classList.add('is-selected');
    stage?.classList.add('is-exiting');
    const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
    if(!reduced)await new Promise(resolve=>setTimeout(resolve,160));
    currentProject=project.id;currentProjectData=project;currentProjectName=project.eventName;applyProjectIdentity(project);await window.app?.loadProject(project.id);navigate('summary',true);
  }

  function openWizard(mode,project=null){wizardMode=mode;wizardProject=project;wizardStep=1;const modal=document.getElementById('projectWizard'),form=document.getElementById('projectWizardForm');form.reset();document.getElementById('wizardName').value=project?.eventName||'';document.getElementById('wizardType').value=project?.projectType||'concert';document.getElementById('wizardDate').value=project?.eventDate||'';document.getElementById('wizardLocation').value=project?.location||'';const accent=project?.accentColor||'blue';const radio=form.querySelector(`[name="accent"][value="${accent}"]`);if(radio)radio.checked=true;document.getElementById('wizardSave').textContent=mode==='edit'?'Guardar identidad':'Crear proyecto';document.getElementById('wizardStatus').hidden=true;setWizardStep(1);updateWizardPreview();modal.hidden=false;document.body.classList.add('modal-open');setTimeout(()=>document.getElementById('wizardName').focus(),40);}
  function closeWizard(){document.getElementById('projectWizard').hidden=true;document.body.classList.remove('modal-open');if(previewUrl){URL.revokeObjectURL(previewUrl);previewUrl='';}}
  function setWizardStep(step){wizardStep=step;document.querySelectorAll('.wizard-step').forEach(node=>node.hidden=Number(node.dataset.step)!==step);document.getElementById('wizardBack').hidden=step===1;document.getElementById('wizardNext').hidden=step===2;document.getElementById('wizardSave').hidden=step===1;document.getElementById('wizardKicker').textContent=`${wizardMode==='edit'?'Editar identidad':'Nuevo proyecto'} · Paso ${step} de 2`;document.getElementById('wizardTitle').textContent=step===1?'Dale nombre al evento.':'Hazlo reconocible.';}
  function wizardIdentity(){return{eventName:document.getElementById('wizardName').value.trim(),projectType:document.getElementById('wizardType').value,eventDate:document.getElementById('wizardDate').value,location:document.getElementById('wizardLocation').value.trim(),accentColor:document.querySelector('[name="accent"]:checked')?.value||'blue'};}
  function updateWizardPreview(){const identity=wizardIdentity(),preview=document.getElementById('wizardPreview');preview.className=`project-preview accent-${identity.accentColor}`;document.getElementById('wizardPreviewName').textContent=identity.eventName||'Tu próximo evento';document.getElementById('wizardPreviewType').textContent=(typeLabels[identity.projectType]||'Proyecto').toUpperCase();if(previewUrl)preview.style.backgroundImage=`linear-gradient(180deg,transparent,rgba(2,4,10,.78)),url("${previewUrl}")`;}
    async function uploadCover(projectId,file){if(!file)return null;if(file.size>10*1024*1024)throw new Error('La portada supera el máximo de 10 MB.');if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('Usa una imagen JPEG, PNG o WebP.');const signed=await Auth.api('/api/uploads/sign',{method:'POST',body:JSON.stringify({category:'cover',projectId,filename:file.name,contentType:file.type,size:file.size})});const upload=await fetch(signed.uploadUrl,{method:'PUT',headers:{'Content-Type':file.type},body:file});if(!upload.ok)throw new Error('No se pudo cargar la portada.');const finalized=await Auth.api(`/api/uploads/${encodeURIComponent(signed.uploadId)}/finalize`,{method:'POST'});return finalized.data.object_key;}
  async function saveWizard(event){event.preventDefault();const status=document.getElementById('wizardStatus'),save=document.getElementById('wizardSave'),identity=wizardIdentity(),file=document.getElementById('wizardCover').files[0];if(!identity.eventName){setWizardStep(1);document.getElementById('wizardName').focus();return;}status.hidden=false;status.dataset.status='warning';status.textContent='Guardando identidad…';save.disabled=true;save.setAttribute('aria-busy','true');try{let projectId=wizardProject?.id;if(wizardMode==='create'){const defaults={eventName:identity.eventName,convocatoriaTime:'18:30',convocatoriaDuration:30,doorsTime:'19:30',doorsDuration:60,showStartMode:'auto',showStartTimeInput:'20:30',blocks:[]};const created=await ApiClient.saveProject({...defaults,...identity});projectId=created.data.id;}let coverKey=wizardProject?.coverKey||null;if(file){try{coverKey=await uploadCover(projectId,file);}catch(error){status.dataset.status='warning';status.textContent=`Proyecto guardado sin portada: ${error.message}`;}}await ApiClient.updateProjectIdentity(projectId,{...identity,coverKey});closeWizard();await loadProjectSelector();const project=projectsCache.find(item=>item.id===projectId);if(project)await openProject(project);}catch(error){status.dataset.status='error';status.textContent=error.message||'No se pudo guardar el proyecto.';}finally{save.disabled=false;save.removeAttribute('aria-busy');}}

  function confirmAction(title,text,action){const modal=document.getElementById('confirmModal');document.getElementById('confirmTitle').textContent=title;document.getElementById('confirmText').textContent=text;const button=document.getElementById('confirmAccept');button.onclick=async()=>{button.disabled=true;try{await action();modal.hidden=true;}finally{button.disabled=false;}};modal.hidden=false;}
  async function requestPasswordReset(projectId,userId){
    confirmAction('Solicitar restablecimiento','Enviaremos un enlace al correo asociado. Nunca podremos ver su contraseña.',async()=>{
      if(userId){await Auth.api(`/api/projects/${encodeURIComponent(projectId)}/members/${encodeURIComponent(userId)}/password-reset`,{method:'POST'});return;}
      const user=await Auth.currentUser();if(!user?.email)throw new Error('No se pudo identificar el correo de la sesión.');await Auth.forgotPassword(user.email);
    });
  }
  async function projectAction(action,project){if(action==='edit')openWizard('edit',project);if(action==='duplicate'){await ApiClient.duplicateProject(project.id);await loadProjectSelector();}if(action==='delete')confirmAction('Eliminar evento',`Se eliminará “${project.eventName}”. Esta acción no se puede deshacer.`,async()=>{await ApiClient.deleteProject(project.id);if(currentProject===project.id){currentProject='';currentProjectData=null;currentProjectName='Elige tu evento';}await loadProjectSelector();});}

  async function loadSummary(){if(!currentProjectData&&currentProject){if(!projectsCache.length)await loadProjects();currentProjectData=projectsCache.find(project=>project.id===currentProject)||null;}if(!currentProjectData)return navigate('projects',true);currentProjectName=currentProjectData.eventName;applyProjectIdentity(currentProjectData);document.getElementById('summaryIdentityName').textContent=currentProjectName;document.getElementById('summaryIdentity').innerHTML=`<span>${esc(typeLabels[currentProjectData.projectType]||'Proyecto')}</span><span>${dateLabel(currentProjectData.eventDate)}</span><span>${esc(currentProjectData.location||'Ubicación por definir')}</span><strong>${roleLabel(currentProjectData.permission)}</strong>`;const teamMeta=document.getElementById('summaryTeamMeta');if(teamMeta){try{const [members,invitations]=await Promise.all([Auth.api(`/api/projects/${encodeURIComponent(currentProject)}/members`),canManage(currentProjectData)?Auth.api(`/api/projects/${encodeURIComponent(currentProject)}/invitations`):Promise.resolve({data:[]})]);const memberCount=Math.max(0,(members.data||[]).length);const pendingCount=(invitations.data||[]).filter(item=>item.effective_status==='pending').length;teamMeta.innerHTML=`<span><strong>${memberCount}</strong> miembro${memberCount===1?'':'s'}</span>${canManage(currentProjectData)?`<a href="/team?project=${encodeURIComponent(currentProject)}" data-route="team">${pendingCount?`${pendingCount} invitación${pendingCount===1?'':'es'} pendiente${pendingCount===1?'':'s'}`:'Gestionar equipo'}</a>`:''}`;}catch(error){teamMeta.textContent='No se pudo cargar el estado del equipo.';teamMeta.dataset.status='warning';}}updateProjectUI();}
  function memberRow(member,manageable){const profile=member.profiles||{},name=`${profile.first_name||''} ${profile.last_name||''}`.trim()||profile.email||'Usuario',initials=name.split(/\s+/).slice(0,2).map(part=>part[0]).join('').toUpperCase();const owner=member.role==='owner';return `<div class="team-row"><span class="member-avatar">${esc(initials)}</span><div><strong>${esc(name)}</strong><small>${esc(profile.email||'')}</small></div><span class="member-date">${member.created_at?new Date(member.created_at).toLocaleDateString('es-CL'):'—'}</span>${manageable&&!owner?`<select class="team-role-select" data-member-role="${esc(profile.id)}"><option value="editor" ${member.role==='editor'?'selected':''}>Director</option><option value="viewer" ${member.role==='viewer'?'selected':''}>Observador</option></select><button class="team-remove" data-remove-member="${esc(profile.id)}" type="button">Remover</button><button class="team-reset" data-reset-member="${esc(profile.id)}" type="button">Solicitar restablecimiento</button>`:`<span class="shell-role">${roleLabel(member.role)}</span>`}</div>`;}
  async function loadTeam(){const status=document.getElementById('shellTeamStatus'),membersBox=document.getElementById('shellMembers'),invitesBox=document.getElementById('shellInvitations');if(!currentProject)return navigate('projects',true);const manageable=canManage(currentProjectData);document.getElementById('shellInvite').hidden=!manageable;try{const [members,invitations]=await Promise.all([Auth.api(`/api/projects/${encodeURIComponent(currentProject)}/members`),manageable?Auth.api(`/api/projects/${encodeURIComponent(currentProject)}/invitations`):Promise.resolve({data:[]})]);status.textContent=manageable?'Administra accesos y permisos de este proyecto.':'Puedes consultar el equipo asignado a este proyecto.';membersBox.innerHTML=(members.data||[]).map(member=>memberRow(member,manageable)).join('')||emptyState('Tu equipo empieza aquí','Invita a una persona como Director u Observador.',manageable?'<button class="btn btn-secondary" type="button" data-open-invite>Invitar persona</button>':'');const deliveryLabel={sent:'Correo enviado',pending:'Pendiente de entrega',failed:'No entregado',not_configured:'Pendiente de configuración'};invitesBox.innerHTML=manageable?(invitations.data||[]).map(invite=>`<div class="team-row invitation-row"><span class="member-avatar">${invite.role==='editor'?'D':'O'}</span><div><strong>${esc(invite.email)}</strong><small>${roleLabel(invite.role)} · vence ${new Date(invite.expires_at).toLocaleDateString('es-CL')} · ${deliveryLabel[invite.delivery_status]||'Estado no disponible'}</small></div><span class="invite-status status-${invite.effective_status}">${esc(invite.effective_status)}</span>${invite.effective_status==='pending'?`<button type="button" class="team-remove" data-revoke-invite="${invite.id}">Revocar</button>`:''}</div>`).join('')||emptyState('Todo al día','No hay invitaciones pendientes en este proyecto.'):'<p class="shell-muted">Solo el propietario administra invitaciones.</p>';}catch(error){status.textContent=error.message;status.dataset.status='error';}}

  const formatClp=value=>new Intl.NumberFormat('es-CL',{style:'currency',currency:'CLP',maximumFractionDigits:0}).format(Number(value)||0);
  function metricBars(items,labelKey='name') { const rows=Array.isArray(items)?items:[]; const max=Math.max(1,...rows.map(item=>Number(item.count)||0)); return rows.map(item=>`<div class="metric-bar"><div><span>${esc(item[labelKey]||'Sin nombre')}</span><strong>${Number(item.count)||0}</strong></div><i style="--metric-width:${Math.max(2,Math.round((Number(item.count)||0)*100/max))}%"></i></div>`).join('')||'<p class="shell-muted">Aún no hay datos para mostrar.</p>'; }
  function renderTicketeraMetrics(metrics){document.getElementById('metricsDashboard').hidden=false;document.getElementById('metricIssued').textContent=Number(metrics.issued)||0;document.getElementById('metricChecked').textContent=`${Number(metrics.checkedIn)||0} acreditadas`;document.getElementById('metricRevenue').textContent=formatClp(metrics.grossSalesClp);document.getElementById('metricPayments').textContent=`${Number(metrics.approvedTickets)||0} ventas aprobadas · ${Number(metrics.pendingPayments)||0} pendientes`;document.getElementById('metricOccupancy').textContent=`${Number(metrics.occupancyPercent)||0}%`;document.getElementById('metricCapacity').textContent=metrics.capacity?`${metrics.issued} de ${metrics.capacity} entradas`:'Sin aforo definido';document.getElementById('metricPending').textContent=Number(metrics.pendingAttendance)||0;document.getElementById('metricTicketTypes').innerHTML=metricBars((metrics.ticketTypes||[]).map(item=>({...item,count:item.issued})));document.getElementById('metricZones').innerHTML=metricBars((metrics.zones||[]).map(item=>({name:item.zone,count:item.count})));}
  async function loadMetrics(){if(!currentProject)return navigate('projects',true);const status=document.getElementById('metricsStatus'),connector=document.getElementById('ticketeraConnector'),dashboard=document.getElementById('metricsDashboard');status.dataset.status='';status.textContent='Consultando conexión con Ticketera…';connector.innerHTML='';dashboard.hidden=true;try{const connectionResult=await Auth.api(`/api/projects/${encodeURIComponent(currentProject)}/integrations/ticketera`);const connection=connectionResult.data;if(!connection){status.textContent=connectionResult.configured?'Selecciona el evento equivalente en Ticketera.':'Ticketera todavía no está configurada en Render.';if(connectionResult.manageable&&connectionResult.configured){const eventsResult=await Auth.api('/api/integrations/ticketera/events');const options=(eventsResult.data||[]).map(event=>`<option value="${esc(event.id)}">${esc(event.name)}${event.date?` · ${dateLabel(event.date)}`:''}</option>`).join('');connector.innerHTML=`<label class="form-label" for="ticketeraEventSelect">Evento en Ticketera</label><div class="ticketera-connect-row"><select class="form-control" id="ticketeraEventSelect"><option value="">Selecciona un evento</option>${options}</select><button class="btn btn-primary" id="ticketeraConnect" type="button">Conectar</button></div>`;}return;}connector.innerHTML=`<div class="ticketera-connected"><div><span class="shell-eyebrow">Conectado con</span><strong>${esc(connection.external_event_name)}</strong><small>${connection.last_synced_at?`Última actualización ${new Date(connection.last_synced_at).toLocaleString('es-CL')}`:'Esperando primera actualización'}</small></div>${connectionResult.manageable?'<button class="btn btn-secondary" id="ticketeraDisconnect" type="button">Desconectar</button>':''}</div>`;const metricsResult=await Auth.api(`/api/projects/${encodeURIComponent(currentProject)}/metrics/ticketera`);renderTicketeraMetrics(metricsResult.data||{});status.dataset.status='success';status.textContent='Métricas sincronizadas con Ticketera.';}catch(error){status.dataset.status=error.code==='FEATURE_DISABLED'?'warning':'error';status.textContent=error.message||'No pudimos cargar las métricas de Ticketera.';}}

  function ensureThemeControl(){const panel=document.querySelector('#view-settings .shell-form-panel');if(!panel||document.getElementById('shellVisualTheme'))return;const group=document.createElement('div');group.className='form-group theme-control-group';group.innerHTML=`<label class="form-label" for="shellVisualTheme">Estilo del espacio de trabajo</label><select id="shellVisualTheme" class="form-control">${Object.entries(visualThemes).map(([key,theme])=>`<option value="${key}">${theme.label} · ${theme.description}</option>`).join('')}</select><small class="shell-muted">La landing mantiene su identidad pública. Este estilo solo cambia el espacio autenticado.</small>`;const actions=panel.querySelector('.shell-actions');panel.querySelector('.grid-2')?.insertAdjacentElement('afterend',group);if(actions){const button=document.createElement('button');button.className='btn btn-secondary';button.id='shellApplyTheme';button.type='button';button.textContent='Aplicar estilo';actions.appendChild(button);const feedback=document.createElement('small');feedback.id='shellThemeFeedback';feedback.className='shell-muted';feedback.setAttribute('role','status');actions.appendChild(feedback);button.addEventListener('click',async()=>{if(!currentProject||!currentProjectData)return;button.disabled=true;button.setAttribute('aria-busy','true');feedback.textContent='Guardando estilo…';try{const visualTheme=document.getElementById('shellVisualTheme').value;const identity={eventName:currentProjectData.eventName||currentProjectName,projectType:currentProjectData.projectType||'other',eventDate:currentProjectData.eventDate||'',location:currentProjectData.location||'',accentColor:currentProjectData.accentColor||'blue',visualTheme};await ApiClient.updateProjectIdentity(currentProject,identity);currentProjectData={...currentProjectData,visualTheme};projectsCache=projectsCache.map(project=>project.id===currentProject?{...project,visualTheme}:project);applyProjectIdentity(currentProjectData);feedback.dataset.status='success';feedback.textContent='Estilo aplicado correctamente.';}catch(error){feedback.dataset.status='error';feedback.textContent=error.message||'No se pudo aplicar el estilo.';}finally{button.disabled=false;button.removeAttribute('aria-busy');}});}}
  function updateProjectUI(){const name=document.getElementById('navProjectName');if(name){name.textContent=currentProjectName;name.hidden=currentRoute==='projects'||!currentProject;name.title=`Cambiar de evento · ${currentProjectName}`;}['shellLiveLink','summaryLiveLink'].forEach(id=>{const link=document.getElementById(id);if(link)link.href=currentProject?`live.html?project=${encodeURIComponent(currentProject)}`:'live.html';});const title=document.getElementById('summaryProjectTitle');if(title)title.textContent=currentProjectName;const status=document.getElementById('summaryStatus');if(status)status.textContent=currentProject?'Evento listo para operar.':'Selecciona un evento.';const input=document.getElementById('shellEventName');if(input)input.value=currentProjectName==='Elige tu evento'?'':currentProjectName;const pid=document.getElementById('shellProjectId');if(pid)pid.textContent=currentProject?'Identificador interno protegido':'Sin evento seleccionado';const role=document.getElementById('workspaceUserRole');if(role)role.textContent=currentProjectData?roleLabel(currentProjectData.permission):'Cuenta T-Show';ensureThemeControl();const themeSelect=document.getElementById('shellVisualTheme');if(themeSelect)themeSelect.value=currentProjectData?.visualTheme||'nocturne';document.body.classList.toggle('project-selector-active',currentRoute==='projects');}
  function applyProjectIdentity(project){const color=accentHex[project?.accentColor]||accentHex.blue;document.documentElement.style.setProperty('--project-accent',color);document.body.classList.add('workspace-surface');document.body.dataset.visualTheme=visualThemes[project?.visualTheme]?project.visualTheme:'nocturne';}
  function setProject(id,name){currentProject=id||'';currentProjectName=name||currentProjectName;currentProjectData=projectsCache.find(project=>project.id===id)||currentProjectData;applyProjectIdentity(currentProjectData);updateProjectUI();if(currentRoute!=='projects')history.replaceState({route:currentRoute},'',routeUrl(currentRoute));}
  function setSchedulePreview(rows){const next=document.getElementById('summaryNext');if(!next)return;const first=(rows||[])[0];next.textContent=first?`${first.start} · ${first.title}`:'No hay bloques configurados';}
  function setViewLoading(route, loading, label) { const view=views[route]; if(!view)return; view.setAttribute('aria-busy',String(loading)); if(loading){const text=label||`Cargando ${labels[route]||'vista'}…`;view.dataset.loadingLabel=text;view.setAttribute('aria-label',text);}else{delete view.dataset.loadingLabel;view.removeAttribute('aria-label');} }
  async function navigate(route,push){if(!routes.includes(route))route='projects';if(route!=='projects'){if(!currentProject){route='projects';push=true;}else{if(!projectsCache.length)await loadProjects().catch(()=>{});currentProjectData=projectsCache.find(project=>project.id===currentProject)||null;if(!currentProjectData){currentProject='';currentProjectName='Elige tu evento';route='projects';push=true;}}}const old=views[currentRoute];if(old&&old!==views[route]){old.classList.remove('is-active');old.classList.add('is-leaving');setTimeout(()=>old.classList.remove('is-leaving'),150);}currentRoute=route;views[route].classList.add('is-active');document.querySelectorAll('.workspace-nav [data-route]').forEach(link=>{if(link.dataset.route===route)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');});const tools=document.getElementById('workspaceTools');if(tools)tools.classList.toggle('is-active',['metrics','files','settings'].includes(route));document.title=`T-Show · ${labels[route]}`;if(push)history.pushState({route},'',routeUrl(route));updateProjectUI();setViewLoading(route,true,`Cargando ${labels[route]||'vista'}…`);try{if(route==='projects')await loadProjectSelector();if(route==='summary')await loadSummary();if(route==='metrics')await loadMetrics();if(route==='team')await loadTeam();}finally{setViewLoading(route,false);}scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}

  function openInvite(){const modal=document.getElementById('inviteModal');document.getElementById('inviteForm').reset();document.getElementById('inviteStatus').hidden=true;modal.hidden=false;setTimeout(()=>document.getElementById('inviteEmail').focus(),30);}
  function bindActions(){
    document.getElementById('workspaceTutorial').addEventListener('keydown',event=>{if(event.key==='Escape')closeTutorial();if(event.key==='ArrowRight')showTutorialStep(tutorialStep+1);if(event.key==='ArrowLeft')showTutorialStep(tutorialStep-1);});
    document.querySelectorAll('[data-close-tutorial]').forEach(node=>node.addEventListener('click',()=>closeTutorial()));
    document.getElementById('tutorialPrevious').addEventListener('click',()=>showTutorialStep(tutorialStep-1));
    document.getElementById('tutorialNext').addEventListener('click',()=>tutorialStep===tutorialSteps.length-1?closeTutorial():showTutorialStep(tutorialStep+1));
    document.getElementById('tutorialSkip').addEventListener('click',()=>closeTutorial());
    document.getElementById('view-metrics').addEventListener('click',async event=>{const connect=event.target.closest('#ticketeraConnect'),disconnect=event.target.closest('#ticketeraDisconnect'),refresh=event.target.closest('#metricsRefresh');if(refresh){await loadMetrics();return;}if(connect){const externalEventId=document.getElementById('ticketeraEventSelect')?.value;if(!externalEventId){document.getElementById('metricsStatus').textContent='Selecciona un evento de Ticketera.';document.getElementById('metricsStatus').dataset.status='warning';return;}connect.disabled=true;try{await Auth.api(`/api/projects/${encodeURIComponent(currentProject)}/integrations/ticketera`,{method:'PUT',body:JSON.stringify({externalEventId})});await loadMetrics();}finally{connect.disabled=false;}return;}if(disconnect){confirmAction('Desconectar Ticketera','Las métricas dejarán de actualizarse hasta conectar otro evento.',async()=>{await Auth.api(`/api/projects/${encodeURIComponent(currentProject)}/integrations/ticketera`,{method:'DELETE'});await loadMetrics();});}});
    const carousel=document.getElementById('projectCarousel');carousel.addEventListener('scroll',()=>requestAnimationFrame(updateCarouselFocus),{passive:true});carousel.addEventListener('keydown',event=>{if(event.key==='ArrowRight'){event.preventDefault();moveCarousel(1)}if(event.key==='ArrowLeft'){event.preventDefault();moveCarousel(-1)}if((event.key==='Enter'||event.key===' ')&&document.activeElement?.classList.contains('project-card')){event.preventDefault();document.activeElement.click();}});carousel.addEventListener('click',async event=>{const menuButton=event.target.closest('.project-menu-button');if(menuButton){event.stopPropagation();const menu=menuButton.nextElementSibling;menu.hidden=!menu.hidden;menuButton.setAttribute('aria-expanded',String(!menu.hidden));return;}const action=event.target.closest('[data-project-action]');if(action){event.stopPropagation();const card=action.closest('.project-card'),project=projectsCache.find(item=>item.id===card.dataset.projectId);await projectAction(action.dataset.projectAction,project);return;}const card=event.target.closest('.project-card');if(!card)return;if(card.dataset.createProject)openWizard('create');else{const project=projectsCache.find(item=>item.id===card.dataset.projectId);if(project)await openProject(project);}});
    document.querySelector('.carousel-prev').onclick=()=>moveCarousel(-1);document.querySelector('.carousel-next').onclick=()=>moveCarousel(1);
    document.querySelectorAll('[data-close-modal]').forEach(node=>node.onclick=closeWizard);document.getElementById('wizardNext').onclick=()=>{if(!document.getElementById('wizardName').value.trim()){document.getElementById('wizardName').focus();return;}setWizardStep(2);updateWizardPreview();};document.getElementById('wizardBack').onclick=()=>setWizardStep(1);document.getElementById('projectWizardForm').addEventListener('input',updateWizardPreview);document.getElementById('wizardCover').addEventListener('change',event=>{if(previewUrl)URL.revokeObjectURL(previewUrl);previewUrl=event.target.files[0]?URL.createObjectURL(event.target.files[0]):'';updateWizardPreview();});document.getElementById('projectWizardForm').addEventListener('submit',saveWizard);
    document.getElementById('shellInvite').onclick=openInvite;document.getElementById('shellMembers').addEventListener('click',event=>{if(event.target.closest('[data-open-invite]'))openInvite();});document.querySelectorAll('[data-close-invite]').forEach(node=>node.onclick=()=>document.getElementById('inviteModal').hidden=true);document.getElementById('inviteForm').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,status=document.getElementById('inviteStatus'),submit=form.querySelector('button[type="submit"]'),email=document.getElementById('inviteEmail').value.trim(),role=document.querySelector('[name="inviteRole"]:checked').value;status.hidden=false;status.dataset.status='warning';status.textContent='Enviando invitación…';submit?.setAttribute('aria-busy','true');if(submit)submit.disabled=true;try{const result=await Auth.api(`/api/projects/${encodeURIComponent(currentProject)}/invitations`,{method:'POST',body:JSON.stringify({email,role})});const delivery=result.data?.delivery_status;status.dataset.status=delivery==='sent'?'success':delivery==='failed'?'error':'warning';status.textContent=result.message||'Invitación creada.';if(delivery==='sent')setTimeout(()=>{document.getElementById('inviteModal').hidden=true;loadTeam();},650);else loadTeam();}catch(error){status.dataset.status='error';status.textContent=error.message;}finally{submit?.removeAttribute('aria-busy');if(submit)submit.disabled=false;}};
    document.getElementById('shellMembers').addEventListener('change',async event=>{const select=event.target.closest('[data-member-role]');if(!select)return;await Auth.api(`/api/projects/${encodeURIComponent(currentProject)}/members/${encodeURIComponent(select.dataset.memberRole)}`,{method:'PATCH',body:JSON.stringify({role:select.value})});await loadTeam();});document.getElementById('shellMembers').addEventListener('click',event=>{const reset=event.target.closest('[data-reset-member]');if(reset){requestPasswordReset(currentProject,reset.dataset.resetMember);return;}const button=event.target.closest('[data-remove-member]');if(!button)return;confirmAction('Remover miembro','La persona perderá el acceso a este proyecto.',async()=>{await Auth.api(`/api/projects/${encodeURIComponent(currentProject)}/members/${encodeURIComponent(button.dataset.removeMember)}`,{method:'DELETE'});await loadTeam();});});document.getElementById('shellInvitations').addEventListener('click',event=>{const button=event.target.closest('[data-revoke-invite]');if(!button)return;confirmAction('Revocar invitación','El enlace dejará de funcionar inmediatamente.',async()=>{await Auth.api(`/api/invitations/${encodeURIComponent(button.dataset.revokeInvite)}`,{method:'DELETE'});await loadTeam();});});
    document.querySelectorAll('[data-cancel-confirm]').forEach(node=>node.onclick=()=>document.getElementById('confirmModal').hidden=true);
    document.getElementById('shellFile').onchange=async event=>{const file=event.target.files[0],status=document.getElementById('shellFileStatus');if(!file||!currentProject)return;try{status.textContent='Preparando carga segura…';await uploadCover(currentProject,file);status.textContent='Archivo cargado correctamente.';status.dataset.status='success';}catch(error){status.textContent=error.message;status.dataset.status='error';}};
    document.getElementById('shellApplySettings').onclick=()=>{const value=document.getElementById('shellEventName').value.trim();if(value&&document.getElementById('eventName')){document.getElementById('eventName').value=value;currentProjectName=value;window.app?.calculateTiming();updateProjectUI();}};document.getElementById('shellExport').onclick=()=>window.app?.exportCurrentProjectJSON();document.getElementById('shellPrint').onclick=()=>window.app?.print();
    addEventListener('popstate',()=>{currentProject=new URLSearchParams(location.search).get('project')||'';currentProjectData=projectsCache.find(project=>project.id===currentProject)||null;navigate(routeFromLocation(),false);});
  }
  async function init(){document.body.classList.add('workspace-surface');mountBackground();mountNav();mountViews();enhanceGuidance();bindActions();await loadAccountSummary();currentRoute=routeFromLocation();routes.forEach(route=>views[route].classList.remove('is-active'));if(currentRoute!=='projects'&&!currentProject)history.replaceState({route:'projects'},'','/projects');await navigate(currentRoute!=='projects'&&!currentProject?'projects':currentRoute,false);try{if(localStorage.getItem(`tshow_onboarding_v1:${currentAccount?.id||'user'}`)!=='done')setTimeout(startTutorial,550);}catch(_){} }
  window.WorkspaceShell={navigate,setProject,setSchedulePreview,get projectId(){return currentProject;},get canEdit(){return !currentProjectData||['owner','admin','editor'].includes(currentProjectData.permission);},get canReorder(){return !currentProjectData||['owner','admin'].includes(currentProjectData.permission);}};
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
  async function loadNotes(){const status=document.getElementById('notesStatus'),list=document.getElementById('notesList'),filter=document.getElementById('notesFilter');if(!currentProject)return navigate('projects',true);try{const result=await Auth.api(`/api/projects/${encodeURIComponent(currentProject)}/notes`);const notes=result.data||[];const render=()=>{const mode=filter.value;const visible=notes.filter(item=>mode==='script'?item.animator_script.trim():mode==='upcoming'?item.notes.trim()||item.animator_script.trim():true);list.innerHTML=visible.map((item,index)=>`<article class="note-block"><div class="note-block-meta"><span>${String(index+1).padStart(2,'0')}</span><strong>${esc(item.start||'Sin hora')}</strong><span>${esc(item.type||'BLOQUE')}</span></div><h3>${esc(item.title||'Bloque sin nombre')}</h3><div class="note-copy"><div><span class="shell-eyebrow">Guion del animador</span><p>${esc(item.animator_script||'Sin guion definido.')}</p></div><div><span class="shell-eyebrow">Notas operativas</span><p>${esc(item.notes||'Sin notas adicionales.')}</p></div></div></article>`).join('')||emptyState('No encontramos contenido','Prueba otro filtro o agrega el guion desde la Escaleta.','<button class="btn btn-secondary" type="button" data-go="schedule">Abrir Escaleta</button>');};status.textContent=`${notes.length} bloque${notes.length===1?'':'s'} disponible${notes.length===1?'':'s'} en modo lectura.`;render();filter.onchange=render;}catch(error){status.textContent=error.message;status.dataset.status='error';list.innerHTML='';}}
  let notesLoadedProject='';
  setInterval(()=>{if(currentRoute==='notes'&&currentProject!==notesLoadedProject){notesLoadedProject=currentProject;loadNotes();}},250);
})();
